/**
 * Row selection in the preview tables: "select all", selected-row counter,
 * buttons enabled only when rows are selected, confirmation before deleting.
 *
 * @module     local_exammanager/row_selection
 * @copyright  2026 KAMA <ousmane.kama@unchk.edu.sn>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_exammanager/row_selection", ["core/str"], function(Str) {

    return {
        /**
         * @param {String} formSelector CSS selector of the preview form.
         */
        init: function(formSelector) {
            var form = document.querySelector(formSelector);
            if (!form) {
                return;
            }

            var selectAll = form.querySelector('.exammanager-select-all');
            var counter = form.querySelector('[data-region="selection-count"]');
            var buttons = form.querySelectorAll('[data-needs-selection]');
            var strings = {count: '', confirm: ''};

            function rowBoxes() {
                return Array.prototype.slice.call(form.querySelectorAll('.exammanager-row-select'));
            }

            function selectedCount() {
                return rowBoxes().filter(function(box) {
                    return box.checked;
                }).length;
            }

            function refresh() {
                var boxes = rowBoxes();
                var count = selectedCount();

                if (selectAll) {
                    selectAll.checked = boxes.length > 0 && count === boxes.length;
                    selectAll.indeterminate = count > 0 && count < boxes.length;
                }
                if (counter) {
                    counter.textContent = strings.count.replace('{$a}', count);
                }
                Array.prototype.forEach.call(buttons, function(button) {
                    button.disabled = count === 0;
                });
                boxes.forEach(function(box) {
                    var row = box.closest('tr');
                    if (row) {
                        row.classList.toggle('exammanager-row-selected', box.checked);
                    }
                });
            }

            if (selectAll) {
                selectAll.addEventListener('change', function() {
                    rowBoxes().forEach(function(box) {
                        box.checked = selectAll.checked;
                    });
                    refresh();
                });
            }

            form.addEventListener('change', function(e) {
                if (e.target.classList && e.target.classList.contains('exammanager-row-select')) {
                    refresh();
                }
            });

            form.addEventListener('click', function(e) {
                var button = e.target.closest('[data-confirm-delete]');
                if (!button) {
                    return;
                }
                var message = strings.confirm.replace('{$a}', selectedCount());
                // eslint-disable-next-line no-alert
                if (message && !window.confirm(message)) {
                    e.preventDefault();
                }
            });

            refresh();

            Str.get_strings([
                {key: 'bulk_selectioncount', component: 'local_exammanager'},
                {key: 'bulk_confirmdelete', component: 'local_exammanager'}
            ]).then(function(results) {
                strings.count = results[0];
                strings.confirm = results[1];
                refresh();
                return null;
            }).catch(function() {
                return null;
            });
        }
    };
});
